#!/usr/bin/env python3
"""Unpack and run SCANNER + TRADE_LIFECYCLE data-flow hook applicator."""
from __future__ import annotations
import base64, zlib, runpy
from pathlib import Path
B64 = ''
code = zlib.decompress(base64.b64decode(B64))
target = Path(__file__).resolve().parent / "_apply_data_flow_hooks_impl.py"
target.write_bytes(code)
runpy.run_path(str(target), run_name="__main__")
